@Test
void hasAttachmentsShouldReturnTrueWhenNonInlined() throws IOException {
    //Given
    MailboxMessage mailboxMessage = mock(MailboxMessage.class);
    TestId mailboxId = TestId.of(1);
    when(mailboxMessage.getMailboxId()).thenReturn(mailboxId);
    when(mailboxMessage.getModSeq()).thenReturn(ModSeq.first());
    InMemoryMessageId messageId = InMemoryMessageId.of(42);
    when(mailboxMessage.getMessageId()).thenReturn(messageId);
    when(mailboxMessage.getFullContent()).thenReturn(ClassLoader.getSystemResourceAsStream("eml/mailWithHeaders.eml"));
    when(mailboxMessage.createFlags()).thenReturn(new Flags());
    when(mailboxMessage.getUid()).thenReturn(MESSAGE_UID);
    when(mailboxMessage.getAttachments()).thenReturn(ImmutableList.of(MessageAttachmentMetadata.builder().attachment(AttachmentMetadata.builder().messageId(messageId).attachmentId(StringBackedAttachmentId.from("1")).type("text/plain").size(36).build()).isInline(false).build()));
    // When
    IndexableMessage indexableMessage = IndexableMessage.builder().message(mailboxMessage).extractor(new DefaultTextExtractor()).zoneId(ZoneId.of("Europe/Paris")).indexAttachments(IndexAttachments.YES).indexHeaders(IndexHeaders.YES).build().block();
    // Then
    assertThat(indexableMessage.getHasAttachment()).isTrue();
}

