void addedEventShouldIncreaseCurrentQuotaValues() throws Exception {
    Added added = mock(Added.class);
    when(added.getMailboxId()).thenReturn(MAILBOX_ID);
    when(added.getMailboxPath()).thenReturn(MAILBOX_PATH);
