@Test
void extractShouldSetExperimentalAttributeWhenScanningMailets() {
    when(mavenProject.getCompileSourceRoots()).thenReturn(ImmutableList.of("src/test/java/org/apache/james/mailet/experimental"));
    List<MailetMatcherDescriptor> descriptors = testee.extract(mavenProject, log).descriptors();
    MailetMatcherDescriptor experimentalMailet = MailetMatcherDescriptor.builder().name("ExperimentalMailet").fullyQualifiedClassName("org.apache.james.mailet.experimental.ExperimentalMailet").type(Type.MAILET).noInfo().noClassDocs().isExperimental();
    MailetMatcherDescriptor nonExperimentalMailet = MailetMatcherDescriptor.builder().name("NonExperimentalMailet").fullyQualifiedClassName("org.apache.james.mailet.experimental.NonExperimentalMailet").type(Type.MAILET).noInfo().noClassDocs().isNotExperimental();
    assertThat(descriptors).containsOnly(experimentalMailet, nonExperimentalMailet);
}

@Test
void extractShouldSupportArgumentsInConstructor() {
    when(mavenProject.getCompileSourceRoots()).thenReturn(ImmutableList.of("src/test/java/org/apache/james/mailet/constructor"));
    List<MailetMatcherDescriptor> descriptors = testee.extract(mavenProject, log).descriptors();
    MailetMatcherDescriptor mailet = MailetMatcherDescriptor.builder().name("ConstructorMailet").fullyQualifiedClassName("org.apache.james.mailet.constructor.ConstructorMailet").type(Type.MAILET).info("info").noClassDocs().isNotExperimental();
    assertThat(descriptors).containsOnly(mailet);
}

@Test
void extractShouldExcludeAnnotatedClassesWhenScanningMailets() {
    when(mavenProject.getCompileSourceRoots()).thenReturn(ImmutableList.of("src/test/java/org/apache/james/mailet/excluded"));
    List<MailetMatcherDescriptor> descriptors = testee.extract(mavenProject, log).descriptors();
    MailetMatcherDescriptor notExcludedMailet = MailetMatcherDescriptor.builder().name("NotExcludedFromDocumentationMailet").fullyQualifiedClassName("org.apache.james.mailet.excluded.NotExcludedFromDocumentationMailet").type(Type.MAILET).noInfo().noClassDocs().isNotExperimental();
    assertThat(descriptors).containsOnly(notExcludedMailet);
}

