@Test
void remoteDeliveryShouldStart() throws Exception {
    when(mailQueue.deQueue()).thenAnswer(invocation -> {
        countDownLatch.countDown();
        Thread.sleep(TimeUnit.SECONDS.toMillis(2));
        return Flux.never();
    });
    remoteDelivery.init(FakeMailetConfig.builder().setProperty(RemoteDeliveryConfiguration.OUTGOING, QUEUE_NAME.asString()).setProperty(RemoteDeliveryConfiguration.HELO_NAME, "Hello_name").build());
    countDownLatch.await();
    verify(mailQueue).deQueue();
}

