@Test
void remoteDeliveryShouldAddEmailToSpool() throws Exception {
    remoteDelivery.init(FakeMailetConfig.builder().build());
    Mail mail = FakeMail.builder().name(MAIL_NAME).recipients(MailAddressFixture.ANY_AT_JAMES).mimeMessage(MimeMessageUtil.mimeMessageFromBytes("h: v\r\n".getBytes(UTF_8))).build();
    remoteDelivery.service(mail);
    assertThat(mailQueue.browse()).toIterable().extracting(MailProjection::from).containsOnly(MailProjection.from(FakeMail.builder().name(MAIL_NAME + RemoteDelivery.NAME_JUNCTION + JAMES_APACHE_ORG).recipient(MailAddressFixture.ANY_AT_JAMES).build()));
}

@Test
void remoteDeliveryShouldPropagateFailures() throws Exception {
    remoteDelivery.init(FakeMailetConfig.builder().build());
    doThrow(new MailQueue.MailQueueException("Injected failure")).when(mailQueue).enQueue(any(), any());
    Mail mail = FakeMail.builder().name(MAIL_NAME).recipients(MailAddressFixture.ANY_AT_JAMES).mimeMessage(MimeMessageUtil.mimeMessageFromBytes("h: v\r\n".getBytes(UTF_8))).build();
    assertThatThrownBy(() -> remoteDelivery.service(mail)).isInstanceOf(MailQueue.MailQueueException.class);
}

