    RetryBackoffConfiguration backoffConfiguration = RetryBackoffConfiguration.builder().maxRetries(2).firstBackoff(Duration.ofMillis(1)).jitterFactor(0.5).build();
    InMemoryIntegrationResources resources = InMemoryIntegrationResources.builder().preProvisionnedFakeAuthenticator().fakeAuthorizator().eventBus(new InVMEventBus(new InVmEventDelivery(new RecordingMetricFactory()), backoffConfiguration, eventDeadLetters)).defaultAnnotationLimits().defaultMessageParser().scanningSearchIndex().noPreDeletionHooks().storeQuotaManager().build();
    mailboxManager = resources.getMailboxManager();
    messageIdManager = spy(resources.getMessageIdManager());
    messageFastViewProjection = spy(new MemoryMessageFastViewProjection(new RecordingMetricFactory()));
    MessageContentExtractor messageContentExtractor = new MessageContentExtractor();
    HtmlTextExtractor htmlTextExtractor = new JsoupHtmlTextExtractor();
    FakeAuthenticator authenticator = new FakeAuthenticator();
    authenticator.addUser(BOB, "12345");
    SessionProviderImpl sessionProvider = new SessionProviderImpl(authenticator, FakeAuthorizator.defaultReject());
    listener = spy(new ComputeMessageFastViewProjectionListener(sessionProvider, messageIdManager, messageFastViewProjection, new MessageFastViewPrecomputedProperties.Factory(new Preview.Factory(messageContentExtractor, htmlTextExtractor))));
    resources.getEventBus().register(listener);
    mailboxSession = MailboxSessionUtil.create(BOB);
    MailboxId inboxId = mailboxManager.createMailbox(BOB_INBOX_PATH, mailboxSession).get();
    inboxMessageManager = mailboxManager.getMailbox(inboxId, mailboxSession);
    MailboxId otherBoxId = mailboxManager.createMailbox(BOB_OTHER_BOX_PATH, mailboxSession).get();
    otherBoxMessageManager = mailboxManager.getMailbox(otherBoxId, mailboxSession);
}

