private IMAPServer createImapServer(HierarchicalConfiguration<ImmutableNode> config, InMemoryIntegrationResources inMemoryIntegrationResources) throws Exception {
    memoryIntegrationResources = inMemoryIntegrationResources;
    RecordingMetricFactory metricFactory = new RecordingMetricFactory();
    Set<ConnectionCheck> connectionChecks = defaultConnectionChecks();
    mailboxManager = spy(memoryIntegrationResources.getMailboxManager());
    IMAPServer imapServer = new IMAPServer(DefaultImapDecoderFactory.createDecoder(), new DefaultImapEncoderFactory().buildImapEncoder(), DefaultImapProcessorFactory.createXListSupportingProcessor(mailboxManager, memoryIntegrationResources.getEventBus(), new StoreSubscriptionManager(mailboxManager.getMapperFactory(), mailboxManager.getMapperFactory(), mailboxManager.getEventBus()), null, memoryIntegrationResources.getQuotaManager(), memoryIntegrationResources.getQuotaRootResolver(), metricFactory), new ImapMetrics(metricFactory), new NoopGaugeRegistry(), connectionChecks);
    FileSystemImpl fileSystem = FileSystemImpl.forTestingWithConfigurationFromClasspath();
    imapServer.setFileSystem(fileSystem);
    imapServer.configure(config);
    imapServer.init();
    return imapServer;
}

