@Test
void putAliasSourceContainingNotManagedDomainShouldReturnBadRequest() throws Exception {
    Mockito.when(domainList.containsDomain(any())).thenAnswer(invocation -> invocation.getArgument(0, Domain.class).equals(DOMAIN));
    Map<String, Object> errors = when().put(BOB + SEPARATOR + "sources" + SEPARATOR + "bob@not-managed-domain.tld").then().statusCode(HttpStatus.BAD_REQUEST_400).contentType(ContentType.JSON).extract().body().jsonPath().getMap(".");
    assertThat(errors).containsEntry("statusCode", HttpStatus.BAD_REQUEST_400).containsEntry("type", "InvalidArgument").containsEntry("message", "Source domain 'not-managed-domain.tld' is not managed by the domainList");
}

@Test
void putAliasDestinationContainingNotManagedDomainShouldReturnBadRequest() throws Exception {
    Mockito.when(domainList.containsDomain(any())).thenAnswer(invocation -> invocation.getArgument(0, Domain.class).equals(DOMAIN));
    Map<String, Object> errors = when().put("bob@not-managed-domain.tld" + SEPARATOR + "sources" + SEPARATOR + BOB).then().statusCode(HttpStatus.BAD_REQUEST_400).contentType(ContentType.JSON).extract().body().jsonPath().getMap(".");
    assertThat(errors).containsEntry("statusCode", HttpStatus.BAD_REQUEST_400).containsEntry("type", "InvalidArgument").containsEntry("message", "Domain in the destination is not managed by the DomainList");
}

