@Test
void gcTaskShouldNotRemoveReferencedBlob() {
    BlobId blobId = Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block();
    when(blobReferenceSource.listReferencedBlobs()).thenReturn(Flux.just(blobId));
    String taskId = given().queryParam("scope", "unreferenced").delete().jsonPath().get("taskId");
    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await").then().body("status", is("completed")).body("additionalInformation.referenceSourceCount", is(1)).body("additionalInformation.blobCount", is(1)).body("additionalInformation.gcedBlobCount", is(0)).body("additionalInformation.errorCount", is(0));
    assertThat(blobStore.read(DEFAULT_BUCKET, blobId)).isNotNull();
}

@Test
void gcTaskShouldSuccessWhenMixCase() {
    List<BlobId> referencedBlobIds = IntStream.range(0, 100).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    List<BlobId> orphanBlobIds = IntStream.range(0, 50).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    when(blobReferenceSource.listReferencedBlobs()).thenReturn(Flux.fromIterable(referencedBlobIds));
    clock.setInstant(TIMESTAMP.plusMonths(2).toInstant());
    List<BlobId> unExpiredBlobIds = IntStream.range(0, 30).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    String taskId = given().queryParam("scope", "unreferenced").delete().jsonPath().get("taskId");
    given().basePath(TasksRoutes.BASE).when().get(taskId + "/await").then().body("status", is("completed")).body("additionalInformation.referenceSourceCount", is(referencedBlobIds.size())).body("additionalInformation.blobCount", is(referencedBlobIds.size() + orphanBlobIds.size() + unExpiredBlobIds.size())).body("additionalInformation.gcedBlobCount", Matchers.lessThanOrEqualTo(orphanBlobIds.size())).body("additionalInformation.errorCount", is(0));
    referencedBlobIds.forEach(blobId -> assertThat(blobStore.read(DEFAULT_BUCKET, blobId)).isNotNull());
    unExpiredBlobIds.forEach(blobId -> assertThat(blobStore.read(DEFAULT_BUCKET, blobId)).isNotNull());
}

@Test
void allOrphanBlobIdsShouldRemovedAfterMultipleCallDeleteUnreferenced() {
    List<BlobId> referencedBlobIds = IntStream.range(0, 100).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    List<BlobId> orphanBlobIds = IntStream.range(0, 50).mapToObj(index -> Mono.from(blobStore.save(DEFAULT_BUCKET, UUID.randomUUID().toString(), BlobStore.StoragePolicy.HIGH_PERFORMANCE)).block()).collect(Collectors.toList());
    when(blobReferenceSource.listReferencedBlobs()).thenReturn(Flux.fromIterable(referencedBlobIds));
    clock.setInstant(TIMESTAMP.plusMonths(2).toInstant());
    CALMLY_AWAIT.untilAsserted(() -> {
        String taskId = given().queryParam("scope", "unreferenced").delete().jsonPath().get("taskId");
        given().basePath(TasksRoutes.BASE).when().get(taskId + "/await");
        orphanBlobIds.forEach(blobId -> assertThatThrownBy(() -> blobStore.read(DEFAULT_BUCKET, blobId)).isInstanceOf(ObjectNotFoundException.class));
    });
}

