@Test
void populateShouldUpdateProjection() {
    Rule rule = Rule.builder().id(Rule.Id.of("2")).name("rule 2").conditionGroup(Rule.Condition.of(SUBJECT, CONTAINS, UNSCRAMBLED_SUBJECT)).action(Rule.Action.of(Rule.Action.AppendInMailboxes.withMailboxIds(ImmutableList.of(bobInboxboxId.serialize())))).build();
