    mailRepositoryStore = mock(MailRepositoryStore.class);
    repository = new MemoryMailRepository();
    testee = new MailRepositoryStoreService(mailRepositoryStore);
}

@Test
void listMailRepositoriesShouldReturnEmptyWhenEmpty() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.empty());
    assertThat(testee.listMailRepositories()).isEmpty();
}

@Test
void listMailRepositoriesShouldReturnOneRepositoryWhenOne() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.of(FIRST_REPOSITORY_PATH));
    assertThat(testee.listMailRepositories()).extracting(SingleMailRepositoryResponse::getRepository).containsOnly(FIRST_REPOSITORY_PATH.asString());
}

@Test
void listMailRepositoriesShouldReturnTwoRepositoriesWhentwo() {
    when(mailRepositoryStore.getPaths()).thenReturn(Stream.of(FIRST_REPOSITORY_PATH, SECOND_REPOSITORY_PATH));
    assertThat(testee.listMailRepositories()).extracting(SingleMailRepositoryResponse::getRepository).containsOnly(FIRST_REPOSITORY_PATH.asString(), SECOND_REPOSITORY_PATH.asString());
}

@Test
void listMailsShouldThrowWhenMailRepositoryStoreThrows() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenThrow(new MailRepositoryStore.MailRepositoryStoreException("message"));
    assertThatThrownBy(() -> testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited())).isInstanceOf(MailRepositoryStore.MailRepositoryStoreException.class);
}

@Test
void listMailsShouldReturnEmptyWhenMailRepositoryIsEmpty() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited()).get()).isEmpty();
}

@Test
void listMailsShouldReturnContainedMailKeys() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    repository.store(FakeMail.builder().name(NAME_1.asString()).build());
    repository.store(FakeMail.builder().name(NAME_2.asString()).build());
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.none(), Limit.unlimited()).get()).containsOnly(new MailKeyDTO(NAME_1), new MailKeyDTO(NAME_2));
}

@Test
void listMailsShouldApplyLimitAndOffset() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    repository.store(FakeMail.builder().name(NAME_1.asString()).build());
    repository.store(FakeMail.builder().name(NAME_2.asString()).build());
    repository.store(FakeMail.builder().name("name3").build());
    assertThat(testee.listMails(FIRST_REPOSITORY_PATH, Offset.from(1), Limit.from(1)).get()).containsOnly(new MailKeyDTO(NAME_2));
}

@Test
void retrieveMessageShouldThrownWhenUnknownRepository() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of());
    assertThatThrownBy(() -> testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isNotInstanceOf(NullPointerException.class);
}

@Test
void retrieveMessageShouldThrowWhenMailRepositoryStoreThrows() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenThrow(new MailRepositoryStore.MailRepositoryStoreException("message"));
    assertThatThrownBy(() -> testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isInstanceOf(MailRepositoryStore.MailRepositoryStoreException.class);
}

@Test
void retrieveMessageShouldReturnEmptyWhenMailNotFound() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    assertThat(testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1)).isEmpty();
}

@Test
void retrieveMessageShouldReturnTheMessageWhenMailExists() throws Exception {
    when(mailRepositoryStore.getByPath(FIRST_REPOSITORY_PATH)).thenReturn(Stream.of(repository));
    FakeMail mail = FakeMail.builder().name(NAME_1.asString()).fileName("mail.eml").build();
    repository.store(mail);
    Optional<MimeMessage> mimeMessage = testee.retrieveMessage(FIRST_REPOSITORY_PATH, NAME_1);
    assertThat(mimeMessage).isNotEmpty();
    String eml = IOUtils.toString(new MimeMessageInputStream(mimeMessage.get()), StandardCharsets.UTF_8);
    String expectedContent = ClassLoaderUtils.getSystemResourceAsString("mail.eml");
    assertThat(eml).isEqualToNormalizingNewlines(expectedContent);
}

@Test
void taskShouldBeSerializable() throws Exception {
    ReprocessingAllMailsTask taskWithTargetProcessor = new ReprocessingAllMailsTask(REPROCESSING_SERVICE, REPOSITORY_SIZE, REPOSITORY_PATH, new ReprocessingService.Configuration(TARGET_QUEUE, SOME_TARGET_PROCESSOR, NO_MAX_RETRIES, CONSUME, Limit.unlimited()));
    ReprocessingAllMailsTask taskWithoutTargetProcessor = new ReprocessingAllMailsTask(REPROCESSING_SERVICE, REPOSITORY_SIZE, REPOSITORY_PATH, new ReprocessingService.Configuration(TARGET_QUEUE, NO_PROCESSOR, NO_MAX_RETRIES, !CONSUME, Limit.unlimited()));
    ReprocessingAllMailsTask taskWithLimit = new ReprocessingAllMailsTask(REPROCESSING_SERVICE, REPOSITORY_SIZE, REPOSITORY_PATH, new ReprocessingService.Configuration(TARGET_QUEUE, SOME_TARGET_PROCESSOR, NO_MAX_RETRIES, CONSUME, Limit.limit(10)));
    JsonSerializationVerifier.dtoModule(ReprocessingAllMailsTaskDTO.module(REPROCESSING_SERVICE)).testCase(taskWithTargetProcessor, SERIALIZED_TASK_WITH_TARGET_PROCESSOR).testCase(taskWithoutTargetProcessor, SERIALIZED_TASK_WITHOUT_TARGET_PROCESSOR).testCase(taskWithLimit, "{\"type\":\"reprocessing-all\",\"repositorySize\":5,\"repositoryPath\":\"a\",\"targetQueue\":\"queue\",\"targetProcessor\":\"targetProcessor\",\"consume\":true, \"limit\":10}").verify();
}

@Test
void shouldDeserializePreviousTaskFormat() throws Exception {
    ReprocessingAllMailsTask taskWithTargetProcessor = new ReprocessingAllMailsTask(REPROCESSING_SERVICE, REPOSITORY_SIZE, REPOSITORY_PATH, new ReprocessingService.Configuration(TARGET_QUEUE, SOME_TARGET_PROCESSOR, NO_MAX_RETRIES, CONSUME, Limit.unlimited()));
    JsonTaskSerializer testee = JsonTaskSerializer.of(ReprocessingAllMailsTaskDTO.module(REPROCESSING_SERVICE));
    assertThat(testee.deserialize(OLD_SERIALIZED_TASK)).usingRecursiveComparison(recursiveComparisonConfiguration).isEqualTo(taskWithTargetProcessor);
    String serializedTaskWithLimit = "{\"type\":\"reprocessing-all\",\"repositorySize\":5,\"repositoryPath\":\"a\",\"targetQueue\":\"queue\",\"targetProcessor\":\"targetProcessor\", \"limit\":10}";
    assertThat(testee.deserialize(serializedTaskWithLimit)).usingRecursiveComparison(recursiveComparisonConfiguration).isEqualTo(new ReprocessingAllMailsTask(REPROCESSING_SERVICE, REPOSITORY_SIZE, REPOSITORY_PATH, new ReprocessingService.Configuration(TARGET_QUEUE, SOME_TARGET_PROCESSOR, NO_MAX_RETRIES, CONSUME, Limit.limit(10))));
}

