@Test
void triggeringARepublishNotProcessedMailsShouldCreateATask() {
    when(mailQueueFactory.getQueue(any())).thenReturn(Optional.of(mock(RabbitMQMailQueue.class)));
    given().queryParam("action", "RepublishNotProcessedMails").queryParam("olderThan", "1d").when().post(MailQueueRoutes.BASE_URL + "/spooler").then().statusCode(HttpStatus.CREATED_201);
    given().when().get("/tasks").then().statusCode(HttpStatus.OK_200).body("", hasSize(1));
}

@Test
void triggeringARepublishNotProcessedMailsWhenTheQueueHasNotBeenInitializedShouldFail() {
    when(mailQueueFactory.getQueue(any())).thenReturn(Optional.empty());
    given().queryParam("action", "RepublishNotProcessedMails").queryParam("olderThan", "1d").when().post(MailQueueRoutes.BASE_URL + "/spooler").then().statusCode(HttpStatus.NOT_FOUND_404).body("message", containsString("MailQueueName{value=spooler} can not be found"));
}

@Test
void triggeringARepublishNotProcessedMailsWithAnInvalidOlderThanShouldFail() {
    when(mailQueueFactory.getQueue(any())).thenReturn(Optional.of(mock(RabbitMQMailQueue.class)));
    given().queryParam("action", "RepublishNotProcessedMails").queryParam("olderThan", "invalidValue").when().post(MailQueueRoutes.BASE_URL + "/spooler").then().statusCode(HttpStatus.BAD_REQUEST_400).body("message", containsString("Invalid olderThan")).body("details", containsString("Supplied value do not follow the unit format (number optionally suffixed with a string representing the unit"));
}

