@Test
void serviceShouldWriteMessageAsSpamWhenSpam() throws Exception {
    MimeMessage mimeMessage = MimeMessageUtil.mimeMessageFromStream(ClassLoader.getSystemResourceAsStream("mail/spam/spam8.eml"));
    Mail mail = FakeMail.builder().name("name").remoteAddr("1.55.251.37").recipient("user1@exemple.com").mimeMessage(mimeMessage).build();
    when(rspamdHttpClient.checkV2(any(Mail.class))).thenReturn(Mono.just(AnalysisResult.builder().action(AnalysisResult.Action.REJECT).score(15F).requiredScore(14F).build()));
    mailet.init(FakeMailetConfig.builder().setProperty("rewriteSubject", "true").build());
    mailet.service(mail);
    Collection<PerRecipientHeaders.Header> headersForRecipient = mail.getPerRecipientSpecificHeaders().getHeadersForRecipient(new MailAddress("user1@exemple.com"));
    SoftAssertions.assertSoftly(softly -> {
        softly.assertThat(headersForRecipient.stream().filter(header -> header.getName().equals(RspamdScanner.FLAG_MAIL.asString())).filter(header -> header.getValue().startsWith("YES")).findAny()).isPresent();
        softly.assertThat(headersForRecipient.stream().filter(header -> header.getName().equals(RspamdScanner.STATUS_MAIL.asString())).filter(header -> header.getValue().startsWith("Yes, actions=reject")).findAny()).isPresent();
    });
}

