@Test
void eventShouldCallSpamAssassinSpamLearningWhenTheEventMatches() throws Exception {
    MessageMoveEvent messageMoveEvent = MessageMoveEvent.builder().session(MAILBOX_SESSION).messageMoves(MessageMoves.builder().previousMailboxIds(mailboxId1).targetMailboxIds(spamMailboxId).build()).messageId(MESSAGE_ID).build();
    listener.event(messageMoveEvent);
    verify(spamAssassinLearner).learnSpam(any(), any());
}

